-- Grupo 20 - Caso 8 - MySQL 8.x
-- Ejecutar en una base vacia. Datos sinteticos Faker.

CREATE TABLE sucursal (
    codigo VARCHAR(20) PRIMARY KEY,
    nombre_sucursal VARCHAR(100) NOT NULL,
    direccion VARCHAR(150),
    comuna VARCHAR(80),
    capacidad INT,
    horario_atencion VARCHAR(100),
    activo INT DEFAULT 1,
    CHECK (capacidad > 0)
);

CREATE TABLE cliente (
    rut_cliente VARCHAR(15) PRIMARY KEY,
    nombre VARCHAR(120) NOT NULL,
    correo_electronico VARCHAR(120),
    clasificacion VARCHAR(40),
    activo INT DEFAULT 1
);

CREATE TABLE equipo (
    codigo_interno VARCHAR(30) PRIMARY KEY,
    tipo_equipo VARCHAR(30),
    marca VARCHAR(60),
    modelo VARCHAR(80),
    numero_serie VARCHAR(80),
    fecha_compra DATE,
    estado_conservacion VARCHAR(40),
    activo INT DEFAULT 1
);

CREATE TABLE personal (
    codigo_personal VARCHAR(20) PRIMARY KEY,
    nombre VARCHAR(120) NOT NULL,
    certificaciones VARCHAR(200),
    responsabilidades VARCHAR(200),
    activo INT DEFAULT 1
);

CREATE TABLE repuesto (
    id_repuesto INT PRIMARY KEY,
    nombre_repuesto VARCHAR(120),
    precio DECIMAL(12,2),
    stock INT,
    activo INT DEFAULT 1,
    CHECK (precio >= 0),
    CHECK (stock >= 0)
);

CREATE TABLE computador (
    codigo_interno VARCHAR(30) PRIMARY KEY,
    sistema_operativo VARCHAR(60),
    memoria_ram VARCHAR(40),
    tipo_almacenamiento VARCHAR(60),
    FOREIGN KEY (codigo_interno)
        REFERENCES equipo(codigo_interno)
);

CREATE TABLE telefono_movil (
    codigo_interno VARCHAR(30) PRIMARY KEY,
    imei VARCHAR(25),
    operador VARCHAR(60),
    version_sistema VARCHAR(50),
    FOREIGN KEY (codigo_interno)
        REFERENCES equipo(codigo_interno)
);

CREATE TABLE tablet (
    codigo_interno VARCHAR(30) PRIMARY KEY,
    tamano_pantalla DECIMAL(4,2),
    conectividad VARCHAR(60),
    capacidad VARCHAR(40),
    FOREIGN KEY (codigo_interno)
        REFERENCES equipo(codigo_interno)
);

CREATE TABLE administrativo (
    codigo_personal VARCHAR(20) PRIMARY KEY,
    FOREIGN KEY (codigo_personal)
        REFERENCES personal(codigo_personal)
);

CREATE TABLE tecnico_electronico (
    codigo_personal VARCHAR(20) PRIMARY KEY,
    FOREIGN KEY (codigo_personal)
        REFERENCES personal(codigo_personal)
);

CREATE TABLE especialista_software (
    codigo_personal VARCHAR(20) PRIMARY KEY,
    FOREIGN KEY (codigo_personal)
        REFERENCES personal(codigo_personal)
);

CREATE TABLE supervisor (
    codigo_personal VARCHAR(20) PRIMARY KEY,
    FOREIGN KEY (codigo_personal)
        REFERENCES personal(codigo_personal)
);

CREATE TABLE orden (
    numero_orden INT PRIMARY KEY,
    codigo_sucursal VARCHAR(20) NOT NULL,
    rut_cliente VARCHAR(15) NOT NULL,
    codigo_interno_equipo VARCHAR(30) NOT NULL,
    fecha_recepcion DATE NOT NULL,
    fecha_comprometida DATE NOT NULL,
    problema_informado VARCHAR(255) NOT NULL,
    estado_actual VARCHAR(30),
    FOREIGN KEY (codigo_sucursal)
        REFERENCES sucursal(codigo),
    FOREIGN KEY (rut_cliente)
        REFERENCES cliente(rut_cliente),
    FOREIGN KEY (codigo_interno_equipo)
        REFERENCES equipo(codigo_interno),
    CHECK (fecha_comprometida >= fecha_recepcion)
);

CREATE TABLE diagnostico (
    numero_orden INT,
    numero_diagnostico INT,
    fecha_diagnostico DATE,
    falla_detectada VARCHAR(140),
    nivel_gravedad VARCHAR(30),
    recomendacion_tecnica VARCHAR(200),
    observaciones VARCHAR(255),
    PRIMARY KEY (numero_orden, numero_diagnostico),
    FOREIGN KEY (numero_orden)
        REFERENCES orden(numero_orden)
);

CREATE TABLE tarea (
    id_tarea INT PRIMARY KEY,
    nombre_tarea VARCHAR(120)
);

CREATE TABLE intervencion_tecnica (
    codigo_intervencion INT PRIMARY KEY,
    numero_orden INT NOT NULL,
    codigo_personal VARCHAR(20) NOT NULL,
    id_tarea INT NOT NULL,
    fecha DATE,
    duracion DECIMAL(6,2),
    resultado VARCHAR(80),
    observaciones VARCHAR(255),
    costo_mano_obra DECIMAL(12,2),
    FOREIGN KEY (numero_orden)
        REFERENCES orden(numero_orden),
    FOREIGN KEY (codigo_personal)
        REFERENCES personal(codigo_personal),
    FOREIGN KEY (id_tarea)
        REFERENCES tarea(id_tarea),
    CHECK (duracion > 0),
    CHECK (costo_mano_obra >= 0)
);

CREATE TABLE detalle_repuesto (
    numero_orden INT,
    id_repuesto INT,
    cantidad INT NOT NULL,
    precio_aplicado DECIMAL(12,2) NOT NULL,
    fecha_incorporacion DATE,
    PRIMARY KEY (numero_orden, id_repuesto),
    FOREIGN KEY (numero_orden)
        REFERENCES orden(numero_orden),
    FOREIGN KEY (id_repuesto)
        REFERENCES repuesto(id_repuesto),
    CHECK (cantidad > 0),
    CHECK (precio_aplicado >= 0)
);

CREATE TABLE evaluacion (
    numero_orden INT,
    numero_correlativo INT,
    fecha DATE,
    nota DECIMAL(3,1),
    cumplimiento_plazo INT,
    comentario VARCHAR(255),
    PRIMARY KEY (numero_orden, numero_correlativo),
    FOREIGN KEY (numero_orden)
        REFERENCES orden(numero_orden),
    CHECK (nota BETWEEN 1 AND 7),
    CHECK (cumplimiento_plazo IN (0,1))
);

CREATE TABLE telefono_cliente (
    rut_cliente VARCHAR(15),
    telefono VARCHAR(25),
    PRIMARY KEY (rut_cliente, telefono),
    FOREIGN KEY (rut_cliente)
        REFERENCES cliente(rut_cliente)
);

CREATE TABLE usuario (
    cuenta_usuario VARCHAR(50) PRIMARY KEY,
    nombre_usuario VARCHAR(100),
    codigo_personal VARCHAR(20),
    password_hash VARCHAR(255),
    activo INT DEFAULT 1,
    FOREIGN KEY (codigo_personal)
        REFERENCES personal(codigo_personal)
);

CREATE TABLE rol (
    nombre_rol VARCHAR(40) PRIMARY KEY
);

CREATE TABLE usuario_rol (
    cuenta_usuario VARCHAR(50),
    nombre_rol VARCHAR(40),
    PRIMARY KEY (cuenta_usuario, nombre_rol),
    FOREIGN KEY (cuenta_usuario)
        REFERENCES usuario(cuenta_usuario),
    FOREIGN KEY (nombre_rol)
        REFERENCES rol(nombre_rol)
);

