SHOW TABLES;

SELECT 'sucursal' AS tabla, COUNT(*) AS registros FROM sucursal
UNION ALL
SELECT 'cliente' AS tabla, COUNT(*) AS registros FROM cliente
UNION ALL
SELECT 'equipo' AS tabla, COUNT(*) AS registros FROM equipo
UNION ALL
SELECT 'personal' AS tabla, COUNT(*) AS registros FROM personal
UNION ALL
SELECT 'repuesto' AS tabla, COUNT(*) AS registros FROM repuesto
UNION ALL
SELECT 'computador' AS tabla, COUNT(*) AS registros FROM computador
UNION ALL
SELECT 'telefono_movil' AS tabla, COUNT(*) AS registros FROM telefono_movil
UNION ALL
SELECT 'tablet' AS tabla, COUNT(*) AS registros FROM tablet
UNION ALL
SELECT 'administrativo' AS tabla, COUNT(*) AS registros FROM administrativo
UNION ALL
SELECT 'tecnico_electronico' AS tabla, COUNT(*) AS registros FROM tecnico_electronico
UNION ALL
SELECT 'especialista_software' AS tabla, COUNT(*) AS registros FROM especialista_software
UNION ALL
SELECT 'supervisor' AS tabla, COUNT(*) AS registros FROM supervisor
UNION ALL
SELECT 'orden' AS tabla, COUNT(*) AS registros FROM orden
UNION ALL
SELECT 'diagnostico' AS tabla, COUNT(*) AS registros FROM diagnostico
UNION ALL
SELECT 'tarea' AS tabla, COUNT(*) AS registros FROM tarea
UNION ALL
SELECT 'intervencion_tecnica' AS tabla, COUNT(*) AS registros FROM intervencion_tecnica
UNION ALL
SELECT 'detalle_repuesto' AS tabla, COUNT(*) AS registros FROM detalle_repuesto
UNION ALL
SELECT 'evaluacion' AS tabla, COUNT(*) AS registros FROM evaluacion
UNION ALL
SELECT 'telefono_cliente' AS tabla, COUNT(*) AS registros FROM telefono_cliente
UNION ALL
SELECT 'usuario' AS tabla, COUNT(*) AS registros FROM usuario
UNION ALL
SELECT 'rol' AS tabla, COUNT(*) AS registros FROM rol
UNION ALL
SELECT 'usuario_rol' AS tabla, COUNT(*) AS registros FROM usuario_rol;

-- R2: Porcentaje de equipos por sucursal

CREATE VIEW vista_r2_porcentaje_equipos AS
SELECT s.nombre_sucursal,
       e.tipo_equipo,
       COUNT(o.numero_orden) AS cantidad,
       COUNT(o.numero_orden) * 100.0 /
       (SELECT COUNT(*)
        FROM orden o2
        WHERE o2.codigo_sucursal = s.codigo)
       AS porcentaje
FROM sucursal s, orden o, equipo e
WHERE s.codigo = o.codigo_sucursal
AND o.codigo_interno_equipo = e.codigo_interno
AND e.tipo_equipo IN
('computador','telefono_movil','tablet')
GROUP BY s.codigo, s.nombre_sucursal, e.tipo_equipo;


-- R3: Relacion entre costo y evaluacion

CREATE VIEW vista_r3_costo_evaluacion AS
SELECT o.numero_orden,
       c.nombre,
       e.tipo_equipo,
       s.nombre_sucursal,
       ev.nota,
       COALESCE(
           (SELECT SUM(i.costo_mano_obra)
            FROM intervencion_tecnica i
            WHERE i.numero_orden = o.numero_orden),0)
       +
       COALESCE(
           (SELECT SUM(d.cantidad * d.precio_aplicado)
            FROM detalle_repuesto d
            WHERE d.numero_orden = o.numero_orden),0)
       AS costo_total
FROM orden o, cliente c, equipo e,
     sucursal s, evaluacion ev
WHERE o.rut_cliente = c.rut_cliente
AND o.codigo_interno_equipo = e.codigo_interno
AND o.codigo_sucursal = s.codigo
AND o.numero_orden = ev.numero_orden;


-- R5: Costo promedio por tipo de equipo

CREATE VIEW vista_r5_costo_promedio_equipo AS
SELECT e.tipo_equipo,
       AVG(
           COALESCE(
               (SELECT SUM(i.costo_mano_obra)
                FROM intervencion_tecnica i
                WHERE i.numero_orden = o.numero_orden),0)
           +
           COALESCE(
               (SELECT SUM(d.cantidad * d.precio_aplicado)
                FROM detalle_repuesto d
                WHERE d.numero_orden = o.numero_orden),0)
       ) AS costo_promedio
FROM equipo e, orden o
WHERE e.codigo_interno = o.codigo_interno_equipo
GROUP BY e.tipo_equipo;


-- R6: Fallas con mas intervenciones y costo promedio

CREATE VIEW vista_r6_fallas_intervenciones AS
SELECT d.falla_detectada,
       SUM(
           (SELECT COUNT(*)
            FROM intervencion_tecnica i
            WHERE i.numero_orden = o.numero_orden)
       ) AS cantidad_intervenciones,
       AVG(
           COALESCE(
               (SELECT SUM(i.costo_mano_obra)
                FROM intervencion_tecnica i
                WHERE i.numero_orden = o.numero_orden),0)
           +
           COALESCE(
               (SELECT SUM(r.cantidad * r.precio_aplicado)
                FROM detalle_repuesto r
                WHERE r.numero_orden = o.numero_orden),0)
       ) AS costo_promedio
FROM orden o, equipo e,
     (SELECT DISTINCT numero_orden, falla_detectada
      FROM diagnostico) d
WHERE o.numero_orden = d.numero_orden
AND o.codigo_interno_equipo = e.codigo_interno
GROUP BY d.falla_detectada;


-- R7: Tecnicos con mas intervenciones

CREATE VIEW vista_r7_tecnicos_mano_obra AS
SELECT p.codigo_personal,
       p.nombre,
       COUNT(i.codigo_intervencion) AS cantidad_intervenciones,
       SUM(i.costo_mano_obra) AS total_mano_obra
FROM personal p, intervencion_tecnica i
WHERE p.codigo_personal = i.codigo_personal
AND (
    p.codigo_personal IN
    (SELECT codigo_personal FROM tecnico_electronico)
    OR
    p.codigo_personal IN
    (SELECT codigo_personal FROM especialista_software)
)
GROUP BY p.codigo_personal, p.nombre
HAVING COUNT(i.codigo_intervencion) > 1;


-- R8: Clientes con mas ordenes y costos acumulados

CREATE VIEW vista_r8_clientes_ordenes AS
SELECT c.rut_cliente,
       c.nombre,
       COUNT(o.numero_orden) AS cantidad_ordenes,
       SUM(
           COALESCE(
               (SELECT SUM(i.costo_mano_obra)
                FROM intervencion_tecnica i
                WHERE i.numero_orden = o.numero_orden),0)
           +
           COALESCE(
               (SELECT SUM(d.cantidad * d.precio_aplicado)
                FROM detalle_repuesto d
                WHERE d.numero_orden = o.numero_orden),0)
       ) AS costo_acumulado
FROM cliente c, orden o
WHERE c.rut_cliente = o.rut_cliente
GROUP BY c.rut_cliente, c.nombre;


-- R1: Tipos de equipos con mas ordenes entre fechas

CREATE PROCEDURE procedimiento_r1(
    IN fecha_inicio DATE,
    IN fecha_fin DATE
)
SELECT e.tipo_equipo,
       COUNT(o.numero_orden) AS cantidad_ordenes
FROM equipo e, orden o, sucursal s
WHERE e.codigo_interno = o.codigo_interno_equipo
AND s.codigo = o.codigo_sucursal
AND o.fecha_recepcion BETWEEN fecha_inicio AND fecha_fin
GROUP BY e.tipo_equipo
ORDER BY cantidad_ordenes DESC;


-- R4: Cantidad de ordenes y clientes por sucursal

CREATE PROCEDURE procedimiento_r4(
    IN fecha_inicio DATE,
    IN fecha_fin DATE
)
SELECT s.nombre_sucursal,
       COUNT(o.numero_orden) AS cantidad_ordenes,
       COUNT(DISTINCT c.rut_cliente) AS cantidad_clientes
FROM sucursal s, orden o, cliente c, equipo e
WHERE s.codigo = o.codigo_sucursal
AND c.rut_cliente = o.rut_cliente
AND e.codigo_interno = o.codigo_interno_equipo
AND o.fecha_recepcion BETWEEN fecha_inicio AND fecha_fin
GROUP BY s.codigo, s.nombre_sucursal
ORDER BY cantidad_ordenes DESC;


-- R9: Ordenes con costo superior al promedio de su tipo

CREATE PROCEDURE procedimiento_r9(
    IN tipo VARCHAR(30),
    IN fecha_inicio DATE,
    IN fecha_fin DATE
)
SELECT o.numero_orden,
       e.tipo_equipo,
       COALESCE(
           (SELECT SUM(i.costo_mano_obra)
            FROM intervencion_tecnica i
            WHERE i.numero_orden = o.numero_orden),0)
       +
       COALESCE(
           (SELECT SUM(d.cantidad * d.precio_aplicado)
            FROM detalle_repuesto d
            WHERE d.numero_orden = o.numero_orden),0)
       AS costo_total
FROM orden o, equipo e
WHERE o.codigo_interno_equipo = e.codigo_interno
AND e.tipo_equipo = tipo
AND o.fecha_recepcion BETWEEN fecha_inicio AND fecha_fin
HAVING costo_total >
(
    SELECT AVG(
        COALESCE(
            (SELECT SUM(i2.costo_mano_obra)
             FROM intervencion_tecnica i2
             WHERE i2.numero_orden = o2.numero_orden),0)
        +
        COALESCE(
            (SELECT SUM(d2.cantidad * d2.precio_aplicado)
             FROM detalle_repuesto d2
             WHERE d2.numero_orden = o2.numero_orden),0)
    )
    FROM orden o2, equipo e2
    WHERE o2.codigo_interno_equipo = e2.codigo_interno
    AND e2.tipo_equipo = e.tipo_equipo
    AND o2.fecha_recepcion BETWEEN fecha_inicio AND fecha_fin
)
ORDER BY costo_total DESC;


-- R10: Repuestos utilizados por encima del promedio

CREATE PROCEDURE procedimiento_r10(
    IN sucursal_buscada VARCHAR(20)
)
SELECT s.nombre_sucursal,
       r.nombre_repuesto,
       SUM(d.cantidad) AS cantidad_utilizada
FROM sucursal s, orden o,
     detalle_repuesto d, repuesto r
WHERE s.codigo = o.codigo_sucursal
AND o.numero_orden = d.numero_orden
AND d.id_repuesto = r.id_repuesto
AND s.codigo = sucursal_buscada
GROUP BY s.codigo, s.nombre_sucursal,
         r.id_repuesto, r.nombre_repuesto
HAVING SUM(d.cantidad) >
(
    SELECT SUM(d2.cantidad) /
           COUNT(DISTINCT d2.id_repuesto)
    FROM orden o2, detalle_repuesto d2
    WHERE o2.numero_orden = d2.numero_orden
    AND o2.codigo_sucursal = s.codigo
)
ORDER BY cantidad_utilizada DESC;


-- R11: Clientes con ordenes y evaluaciones
-- superiores al promedio

CREATE PROCEDURE procedimiento_r11(
    IN fecha_inicio DATE,
    IN fecha_fin DATE
)
SELECT c.rut_cliente,
       c.nombre,
       COUNT(DISTINCT o.numero_orden) AS cantidad_ordenes,
       AVG(ev.nota) AS promedio_nota
FROM cliente c
JOIN orden o
ON c.rut_cliente = o.rut_cliente
JOIN equipo e
ON o.codigo_interno_equipo = e.codigo_interno
LEFT JOIN evaluacion ev
ON o.numero_orden = ev.numero_orden
WHERE o.fecha_recepcion BETWEEN fecha_inicio AND fecha_fin
GROUP BY c.rut_cliente, c.nombre
HAVING COUNT(DISTINCT o.numero_orden) >
(
    SELECT COUNT(*) / COUNT(DISTINCT o2.rut_cliente)
    FROM orden o2
    WHERE o2.fecha_recepcion BETWEEN fecha_inicio AND fecha_fin
)
AND AVG(ev.nota) >
(
    SELECT AVG(ev2.nota)
    FROM evaluacion ev2, orden o3
    WHERE ev2.numero_orden = o3.numero_orden
    AND o3.fecha_recepcion BETWEEN fecha_inicio AND fecha_fin
)
ORDER BY cantidad_ordenes DESC;


-- R12: Sucursales con costo promedio superior
-- al promedio general de las sucursales

CREATE PROCEDURE procedimiento_r12(
    IN fecha_inicio DATE,
    IN fecha_fin DATE
)
SELECT s.nombre_sucursal,
       AVG(
           COALESCE(
               (SELECT SUM(i.costo_mano_obra)
                FROM intervencion_tecnica i
                WHERE i.numero_orden = o.numero_orden),0)
           +
           COALESCE(
               (SELECT SUM(d.cantidad * d.precio_aplicado)
                FROM detalle_repuesto d
                WHERE d.numero_orden = o.numero_orden),0)
       ) AS costo_promedio
FROM sucursal s, orden o
WHERE s.codigo = o.codigo_sucursal
AND o.fecha_recepcion BETWEEN fecha_inicio AND fecha_fin
GROUP BY s.codigo, s.nombre_sucursal
HAVING costo_promedio >
(
    SELECT AVG(promedios.costo_sucursal)
    FROM
    (
        SELECT o2.codigo_sucursal,
               AVG(
                   COALESCE(
                       (SELECT SUM(i2.costo_mano_obra)
                        FROM intervencion_tecnica i2
                        WHERE i2.numero_orden = o2.numero_orden),0)
                   +
                   COALESCE(
                       (SELECT SUM(d2.cantidad * d2.precio_aplicado)
                        FROM detalle_repuesto d2
                        WHERE d2.numero_orden = o2.numero_orden),0)
               ) AS costo_sucursal
        FROM orden o2
        WHERE o2.fecha_recepcion BETWEEN fecha_inicio AND fecha_fin
        GROUP BY o2.codigo_sucursal
    ) promedios
)
ORDER BY costo_promedio DESC;


-- EJECUCION DE LOS 12 REQUERIMIENTOS

-- R1

